8	//
9	//  This file defines the TableGen core definitions for the diagnostics
10	//  and diagnostic control.
11	//
12	//===----------------------------------------------------------------------===//
13	
14	// See the Internals Manual, section The Diagnostics Subsystem for an overview.
15	
16	// Define the diagnostic severities.
17	class Severity<string N> {
18	  string Name = N;
19	}
20	def SEV_Ignored : Severity<"Ignored">;
21	def SEV_Remark  : Severity<"Remark">;
22	def SEV_Warning : Severity<"Warning">;
23	def SEV_Error   : Severity<"Error">;
24	def SEV_Fatal   : Severity<"Fatal">;
25	
26	// Define the diagnostic classes.
27	class DiagClass;
28	def CLASS_NOTE      : DiagClass;
29	def CLASS_REMARK    : DiagClass;
30	def CLASS_WARNING   : DiagClass;
31	def CLASS_EXTENSION : DiagClass;
32	def CLASS_ERROR     : DiagClass;
33	def CLASS_TRAP      : DiagClass;
34	
35	// Responses to a diagnostic in a SFINAE context.
36	class SFINAEResponse;
37	def SFINAE_SubstitutionFailure : SFINAEResponse;
38	def SFINAE_Suppress            : SFINAEResponse;
39	def SFINAE_Report              : SFINAEResponse;
40	def SFINAE_AccessControl       : SFINAEResponse;
41	
42	// Textual substitutions which may be performed on the text of diagnostics
43	class TextSubstitution<string Text> {
44	  string Substitution = Text;
45	  // TODO: These are only here to allow substitutions to be declared inline with
46	  // diagnostics
47	  string Component = "";
48	  string CategoryName = "";
49	  bit Deferrable = 0;
50	}
51	
52	// Diagnostic Categories.  These can be applied to groups or individual
53	// diagnostics to specify a category.
54	class DiagCategory<string Name> {
55	  string CategoryName = Name;
56	}
57	
58	// Diagnostic Groups.
59	class DiagGroup<string Name, list<DiagGroup> subgroups = [], code docs = [{}]> {
60	  string GroupName = Name;
61	  list<DiagGroup> SubGroups = subgroups;
62	  string CategoryName = "";
63	  code Documentation = docs;
64	}
65	class InGroup<DiagGroup G> { DiagGroup Group = G; }
66	//class IsGroup<string Name> { DiagGroup Group = DiagGroup<Name>; }
67	
68	// This defines documentation for diagnostic groups.
69	include "DiagnosticDocs.td"
70	
71	// This defines all of the named diagnostic categories.
72	include "DiagnosticCategories.td"
73	
74	// This defines all of the named diagnostic groups.
75	include "DiagnosticGroups.td"
76	
77	
78	// All diagnostics emitted by the compiler are an indirect subclass of this.
79	class Diagnostic<string summary, DiagClass DC, Severity defaultmapping> {
80	  /// Component is specified by the file with a big let directive.
81	  string         Component = ?;
82	  string         Summary = summary;
83	  DiagClass      Class = DC;
84	  SFINAEResponse SFINAE = SFINAE_Suppress;
85	  bit            AccessControl = 0;
86	  bit            WarningNoWerror = 0;
87	  bit            ShowInSystemHeader = 0;
88	  bit            ShowInSystemMacro = 1;
89	  bit            Deferrable = 0;
90	  Severity       DefaultSeverity = defaultmapping;
91	  DiagGroup      Group;
92	  string         CategoryName = "";
93	}
94	
95	class SFINAEFailure {
96	  SFINAEResponse SFINAE = SFINAE_SubstitutionFailure;
97	}
98	class NoSFINAE {
99	  SFINAEResponse SFINAE = SFINAE_Report;
100	}
101	class AccessControl {
102	  SFINAEResponse SFINAE = SFINAE_AccessControl;
103	}
104	
105	class ShowInSystemHeader {
106	  bit ShowInSystemHeader = 1;
107	}
108	
109	class SuppressInSystemHeader {
110	  bit ShowInSystemHeader = 0;
111	}
112	
113	class ShowInSystemMacro {
114	  bit ShowInSystemMacro = 1;
115	}
116	
117	class SuppressInSystemMacro {
118	  bit ShowInSystemMacro = 0;
119	}
120	
121	class Deferrable {
122	  bit Deferrable = 1;
123	}
124	
125	class NonDeferrable {
126	  bit Deferrable = 0;
127	}
128	
129	// FIXME: ExtWarn and Extension should also be SFINAEFailure by default.
130	class Error<string str>     : Diagnostic<str, CLASS_ERROR, SEV_Error>, SFINAEFailure {
131	  bit ShowInSystemHeader = 1;
132	}
133	// Warnings default to on (but can be default-off'd with DefaultIgnore).
134	// This is used for warnings about questionable code; warnings about
135	// accepted language extensions should use Extension or ExtWarn below instead.
136	class Warning<string str>   : Diagnostic<str, CLASS_WARNING, SEV_Warning>;
137	// Remarks can be turned on with -R flags and provide commentary, e.g. on
138	// optimizer decisions.
139	class Remark<string str>    : Diagnostic<str, CLASS_REMARK, SEV_Ignored>;
140	// Extensions are warnings about accepted language extensions.
141	// Extension warnings are default-off but enabled by -pedantic.
142	class Extension<string str> : Diagnostic<str, CLASS_EXTENSION, SEV_Ignored>;
143	// ExtWarns are warnings about accepted language extensions.
144	// ExtWarn warnings are default-on.
145	class ExtWarn<string str>   : Diagnostic<str, CLASS_EXTENSION, SEV_Warning>;
146	// Notes can provide supplementary information on errors, warnings, and remarks.
147	class Note<string str>      : Diagnostic<str, CLASS_NOTE, SEV_Fatal/*ignored*/>;
148	// Trap messages attached to traps in debug info.
149	class Trap<string str>      : Diagnostic<str, CLASS_TRAP, SEV_Fatal/*ignored*/>;
150	
151	class DefaultIgnore { Severity DefaultSeverity = SEV_Ignored; }
152	class DefaultWarn   { Severity DefaultSeverity = SEV_Warning; }
153	class DefaultError  { Severity DefaultSeverity = SEV_Error; }
154	class DefaultFatal  { Severity DefaultSeverity = SEV_Fatal; }
155	class DefaultWarnNoWerror {
156	  bit WarningNoWerror = 1;
157	}
158	class DefaultRemark { Severity DefaultSeverity = SEV_Remark; }
159	
160	class CompatWarningId<string name, int std, string diag, string diag_pre> {
161	  string Component = ?;
162	  string Name = name;
163	  string Diag = diag;
164	  string DiagPre = diag_pre;
165	  int Std = std;
166	
167	  // This is unused, but Tablegen will complain if it's missing because we define
168	  // the compatibility ids in the same place as the other diagnostics (which means
169	  // that we'll be inside a 'let CategoryName = "" in { ... }' block).
170	  string CategoryName = ?;
171	}
172	
173	// C++ compatibility warnings.
174	multiclass CXXCompat<
175	    string message,
176	    int std_ver,
177	    bit ext_warn = true,
178	    string std_ver_override = ""#std_ver> {
179	    // 'X is a C++YZ extension'.
180	    def compat_pre_cxx#std_ver#_#NAME :
181	        Diagnostic<!strconcat(message, " a C++", std_ver_override,  " extension"),
182	                   CLASS_EXTENSION,
183	                   !if(ext_warn, SEV_Warning, SEV_Ignored)>,
184	        InGroup<!cast<DiagGroup>("CXX"#std_ver)>;
185	
186	    // 'X is incompatible with C++98' (if std_ver == 11).
187	    // 'X is incompatible with C++ standards before C++YZ' (otherwise).
188	    def compat_cxx#std_ver#_#NAME :
189	        Warning<!if(!eq(std_ver, 11),
190	                    !strconcat(message, " incompatible with C++98"),
191	                    !strconcat(message, " incompatible with C++ standards before C++", std_ver_override))>,
192	        InGroup<!cast<DiagGroup>(!if(!eq(std_ver, 11),
193	                                     "CXX98Compat",
194	                                     "CXXPre"#std_ver#"Compat"))>,
195	        DefaultIgnore;
196	
197	    def : CompatWarningId<
198	        NAME, std_ver,
199	        "compat_cxx"#std_ver#"_"#NAME,
200	        "compat_pre_cxx"#std_ver#"_"#NAME>;
201	}
202	
203	// These generate pairs of C++ compatibility warnings of the form:
204	//
205	//    - compat_cxx<std>_<name>
206	//    - compat_pre_cxx<std>_<name>
207	//
208	// The 'compat_cxx...' warning is intended to be issued in C++<std> mode,
209	// and the 'compat_pre_cxx...' warning in C++ modes before C++<std>.
210	//
211	// Example:
212	//
213	//   defm inline_variable : CXX17Compat<"inline variables are">;
214	//
215	// This generates two warnings:
216	//
217	//   - compat_cxx17_inline_variable:     'inline variables are incompatible with C++ standards before C++17'
218	//   - compat_pre_cxx17_inline_variable: 'inline variables are a C++17 extension'
219	//
220	multiclass CXX11Compat<string message, bit ext_warn = true> : CXXCompat<message, 11, ext_warn>;
221	multiclass CXX14Compat<string message, bit ext_warn = true> : CXXCompat<message, 14, ext_warn>;
222	multiclass CXX17Compat<string message, bit ext_warn = true> : CXXCompat<message, 17, ext_warn>;
223	multiclass CXX20Compat<string message, bit ext_warn = true> : CXXCompat<message, 20, ext_warn>;
224	multiclass CXX23Compat<string message, bit ext_warn = true> : CXXCompat<message, 23, ext_warn>;
225	multiclass CXX26Compat<string message, bit ext_warn = true> : CXXCompat<message, 26, ext_warn, "2c">;
226	
